<script lang="ts">
  import { browser } from '$app/environment';
  import Icon from '$lib/components/Icon.svelte';
  import StatusPill from '$lib/components/StatusPill.svelte';
  import { payoutHistory, creatorProfile, connectStripe } from '$lib/stores/creator';

  $: gross = $payoutHistory.reduce((sum, payout) => sum + Number(payout.gross || 0), 0);
  $: refunds = $payoutHistory.reduce((sum, payout) => sum + Number(payout.refunds || 0), 0);
  $: fees = $payoutHistory.reduce((sum, payout) => sum + Number(payout.fees || 0), 0);
  $: net = $payoutHistory.reduce((sum, payout) => sum + Number(payout.net || 0), 0);
  $: pending = $payoutHistory.filter((payout) => payout.status === 'Pending').reduce((sum, payout) => sum + Number(payout.net || 0), 0);
  $: paid = $payoutHistory.filter((payout) => payout.status === 'Paid').reduce((sum, payout) => sum + Number(payout.net || 0), 0);
  $: connected = $creatorProfile.connectedAccount === 'Stripe ready';

  function exportLedger() {
    if (!browser) return;
    const rows = [['Payout','Date','Gross','Refunds','Fees','Net','Status'], ...$payoutHistory.map((p) => [p.id,p.date,p.gross,p.refunds,p.fees,p.net,p.status])];
    const csv = rows.map((row) => row.map((value) => `"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type:'text/csv;charset=utf-8' }));
    const link = document.createElement('a'); link.href=url; link.download='assetguru-payout-ledger.csv'; link.click(); URL.revokeObjectURL(url);
  }
</script>

<svelte:head><title>Earnings & Payouts — Creator Hub — AssetGuru</title></svelte:head>
<header class="page-head"><div><span class="eyebrow">Creator finance</span><h1>Earnings and <span class="gradient-text">payouts.</span></h1><p>See what sold, what AssetGuru retained, what was adjusted and what reached your connected Stripe account.</p></div><div class="head-actions"><button class="button button-secondary" type="button" onclick={exportLedger} disabled={!$payoutHistory.length}><Icon name="download" size={17}/> Download ledger</button></div></header>

<div class="balance-grid">
  <section class="available glass"><span class="eyebrow">Pending settlement</span><strong>£{pending.toFixed(2)}</strong><p>{$creatorProfile.payoutSchedule || 'Managed by Stripe'}.</p><div><Icon name={connected ? 'check' : 'alert'} size={18}/><span><b>{$creatorProfile.connectedAccount}</b><small>{connected ? 'Charges and payouts are enabled.' : 'Complete Stripe onboarding before selling.'}</small></span></div><button class="button button-primary" type="button" onclick={connectStripe}>{connected ? 'Open Stripe account' : 'Connect Stripe'}</button></section>
  <section class="money-card glass"><Icon name="chart" size={21}/><span><small>Gross processed</small><b>£{gross.toFixed(2)}</b><em>All recorded settlements</em></span></section>
  <section class="money-card glass"><Icon name="tag" size={21}/><span><small>Marketplace fees</small><b>£{fees.toFixed(2)}</b><em>{$creatorProfile.commission || 15}% current commission</em></span></section>
  <section class="money-card glass"><Icon name="alert" size={21}/><span><small>Refunds & adjustments</small><b>£{refunds.toFixed(2)}</b><em>Reconciled against payouts</em></span></section>
  <section class="money-card glass"><Icon name="check" size={21}/><span><small>Paid to date</small><b>£{paid.toFixed(2)}</b><em>Successful Stripe transfers</em></span></section>
</div>

<div class="finance-grid">
  <section class="breakdown glass"><div class="panel-head"><div><span class="eyebrow">Live ledger</span><h2>Earnings breakdown</h2></div><b>Net £{net.toFixed(2)}</b></div><div class="waterfall"><div class="positive" style="--h:100%"><span>Gross sales</span><i></i><b>£{gross.toFixed(2)}</b></div><div class="negative" style="--h:{gross ? Math.max(8, Math.min(100, fees/gross*100)) : 0}%"><span>Commission</span><i></i><b>−£{fees.toFixed(2)}</b></div><div class="negative" style="--h:{gross ? Math.max(8, Math.min(100, refunds/gross*100)) : 0}%"><span>Refunds</span><i></i><b>−£{refunds.toFixed(2)}</b></div><div class="positive net" style="--h:{gross ? Math.max(8, Math.min(100, net/gross*100)) : 0}%"><span>Net earnings</span><i></i><b>£{net.toFixed(2)}</b></div></div><div class="fee-note"><Icon name="shield" size={18}/><span><b>Transparent fee model</b><small>Every completed order stores its commission, vendor net and later refund adjustments in the production ledger.</small></span></div></section>

  <section class="payout-settings glass"><div class="panel-head"><div><span class="eyebrow">Settlement</span><h2>Stripe Connect</h2></div></div><div class="account"><span class="stripe">S</span><div><b>Connected marketplace account</b><small>{$creatorProfile.connectedAccount} · GBP settlement</small></div><StatusPill status={connected ? 'Paid' : 'Pending'}/></div><div class="switch"><Icon name="lock" size={18}/><span><b>Payout controls are managed by Stripe</b><small>Bank details, identity checks and payout timing remain in your secure Stripe-hosted account.</small></span></div><button class="button button-secondary" type="button" onclick={connectStripe}>{connected ? 'Manage Stripe account' : 'Resume onboarding'}</button><a href="/support">Questions about payouts? Open finance support →</a></section>

  <section class="history glass"><div class="panel-head"><div><span class="eyebrow">Ledger</span><h2>Payout history</h2></div><button type="button" onclick={exportLedger} disabled={!$payoutHistory.length}><Icon name="download" size={15}/> Export ledger</button></div><div class="history-head"><span>Payout</span><span>Date</span><span>Gross</span><span>Refunds</span><span>Fees</span><span>Net paid</span><span>Status</span></div>{#if $payoutHistory.length}{#each $payoutHistory as payout}<article><span><b>{payout.id}</b><small>Stripe settlement</small></span><time>{payout.date}</time><strong>£{payout.gross.toFixed(2)}</strong><span>−£{payout.refunds.toFixed(2)}</span><span>−£{payout.fees.toFixed(2)}</span><strong class="net">£{payout.net.toFixed(2)}</strong><StatusPill status={payout.status}/></article>{/each}{:else}<div class="empty-ledger"><Icon name="chart" size={25}/><span><b>No settlements yet</b><small>Stripe transfers will appear after the first completed sale.</small></span></div>{/if}</section>

  <section class="tax glass"><Icon name="library" size={26}/><div><span class="eyebrow">Records</span><h2>Tax and invoice records</h2><p>Use the downloadable AssetGuru ledger together with the statements available in your Stripe account.</p></div><button class="button button-secondary" type="button" onclick={exportLedger} disabled={!$payoutHistory.length}>Download current ledger</button></section>
</div>
